import{c as a,Q as r,j as e,m as o}from"./chunks/framework.D55kK6e8.js";const b=JSON.parse('{"title":"数据看板","description":"","frontmatter":{},"headers":[],"relativePath":"guide/dashboard.md","filePath":"guide/dashboard.md"}'),d={name:"guide/dashboard.md"};function l(i,t,n,h,s,u){return r(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="数据看板" tabindex="-1">数据看板 <a class="header-anchor" href="#数据看板" aria-label="Permalink to &quot;数据看板&quot;">​</a></h1><p>数据看板是系统的首页，提供工单数据的可视化展示和实时监控。</p><h2 id="功能特性" tabindex="-1">功能特性 <a class="header-anchor" href="#功能特性" aria-label="Permalink to &quot;功能特性&quot;">​</a></h2><h3 id="时间范围筛选" tabindex="-1">时间范围筛选 <a class="header-anchor" href="#时间范围筛选" aria-label="Permalink to &quot;时间范围筛选&quot;">​</a></h3><p>支持多种时间范围查看：</p><ul><li><strong>快速选择</strong> - 本周、本月、本季度</li><li><strong>按月份</strong> - 选择具体月份</li><li><strong>全部</strong> - 查看所有历史数据</li></ul><h3 id="核心统计" tabindex="-1">核心统计 <a class="header-anchor" href="#核心统计" aria-label="Permalink to &quot;核心统计&quot;">​</a></h3><p>看板顶部展示核心指标卡片：</p><table tabindex="0"><thead><tr><th>指标</th><th>说明</th></tr></thead><tbody><tr><td>总工单数</td><td>当前范围内的工单总数</td></tr><tr><td>待处理</td><td>状态为&quot;待处理&quot;的工单数</td></tr><tr><td>处理中</td><td>状态为&quot;处理中&quot;的工单数</td></tr><tr><td>已解决</td><td>状态为&quot;已解决&quot;或&quot;已关闭&quot;的工单数</td></tr></tbody></table><h3 id="图表展示" tabindex="-1">图表展示 <a class="header-anchor" href="#图表展示" aria-label="Permalink to &quot;图表展示&quot;">​</a></h3><ul><li><strong>工单趋势图</strong> - 展示工单创建和解决的趋势</li><li><strong>分类分布</strong> - 按工单类型统计</li><li><strong>优先级分布</strong> - 按优先级统计</li><li><strong>科室分布</strong> - 按申请科室统计</li></ul><h3 id="最新工单" tabindex="-1">最新工单 <a class="header-anchor" href="#最新工单" aria-label="Permalink to &quot;最新工单&quot;">​</a></h3><p>展示最近创建的 10 条工单，包含状态、优先级、标题、科室、登记人、处理人和创建时间。</p><h2 id="自动刷新" tabindex="-1">自动刷新 <a class="header-anchor" href="#自动刷新" aria-label="Permalink to &quot;自动刷新&quot;">​</a></h2><p>看板支持自动刷新功能：</p><ul><li>默认关闭，可手动开启</li><li>开启后每 60 秒自动刷新数据</li><li>支持手动点击刷新按钮</li></ul><h2 id="看板模式" tabindex="-1">看板模式 <a class="header-anchor" href="#看板模式" aria-label="Permalink to &quot;看板模式&quot;">​</a></h2><p>系统支持免登录的看板模式，配置 <code>dashboardConfig.enabled = true</code> 后，系统会自动使用配置的账号登录并跳转到看板页面，适用于公共展示场景。</p>',18)])])}const q=a(d,[["render",l]]);export{b as __pageData,q as default};
